var e=[{slug:`casa-verde`,name:`Casa Verde`,meta:{en:`Italian · Kyiv`,ua:`Італійська · Київ`},text:{en:`Hand-rolled pasta and a wood-fired oven, with a menu that follows the seasons.`,ua:`Паста ручної роботи та піч на дровах, а меню змінюється разом із сезонами.`},about:{en:`Casa Verde is a neighbourhood kitchen built around a wood-fired oven. The pasta is rolled by hand every morning, and the short menu changes with what the market has that week.`,ua:`Casa Verde є кухнею для своїх, збудованою навколо печі на дровах. Паста ручної роботи, яку розкатують щоранку, а коротке меню змінюється залежно від того, що цього тижня є на ринку.`},dishes:[{name:{en:`Tagliatelle with slow ragù`,ua:`Тальятеле з повільним рагу`},text:{en:`Egg pasta and beef simmered for four hours.`,ua:`Яєчна паста й яловичина, що готується чотири години.`}},{name:{en:`Charred seasonal vegetables`,ua:`Обпечені сезонні овочі`},text:{en:`From the oven, finished with herbs and lemon.`,ua:`З печі, із зеленню та лимоном.`}},{name:{en:`Burnt honey panna cotta`,ua:`Панна котта з карамелізованим медом`},text:{en:`Soft, cold and slightly bitter.`,ua:`Ніжна, холодна й трохи гірка.`}}],address:{en:`12 Garden Street, Kyiv`,ua:`вул. Садова, 12, Київ`},hours:{en:`Tue–Sun, 12:00–23:00`,ua:`Вт–Нд, 12:00–23:00`},price:{en:`Mid-range`,ua:`Середній чек`},phone:`+380 44 000 00 01`,wifi:{network:`CasaVerde_Guest`,password:`pasta2026`},payment:{en:`Cards and cash`,ua:`Картки та готівка`},features:[{en:`Outdoor seating`,ua:`Літня тераса`},{en:`Vegetarian options`,ua:`Вегетаріанські страви`},{en:`Reservations recommended`,ua:`Бажано бронювати`}],menu:[`weeknight-tomato-pasta`,`no-knead-bread`]},{slug:`sakura-table`,name:`Sakura Table`,meta:{en:`Japanese · Lviv`,ua:`Японська · Львів`},text:{en:`A small counter where the chef prepares each course in front of you.`,ua:`Невелика стійка, де шеф готує кожну страву просто перед гостями.`},about:{en:`Sakura Table seats twelve at a single counter. The chef prepares each course in front of the guests, from the first cold dish to the final bowl of rice.`,ua:`Sakura Table вміщує дванадцятьох гостей за єдиною стійкою. Шеф готує кожну страву на очах у гостей, від першої холодної закуски до останньої піали рису.`},dishes:[{name:{en:`Seasonal sashimi plate`,ua:`Сашимі за сезоном`},text:{en:`Three fish, cut to order.`,ua:`Три види риби, нарізані на замовлення.`}},{name:{en:`Clear dashi soup`,ua:`Прозорий суп даші`},text:{en:`Kombu and bonito, simmered gently.`,ua:`Комбу й боніто, що повільно томляться.`}},{name:{en:`Grilled rice ball`,ua:`Онігірі на грилі`},text:{en:`Crisp outside, soft inside.`,ua:`Хрусткі ззовні, м’які всередині.`}}],address:{en:`5 Cherry Lane, Lviv`,ua:`вул. Вишнева, 5, Львів`},hours:{en:`Wed–Sun, 18:00–22:30`,ua:`Ср–Нд, 18:00–22:30`},price:{en:`Higher`,ua:`Вищий чек`},phone:`+380 32 000 00 02`,wifi:{network:`SakuraTable`,password:`dashi2026`},payment:{en:`Cards only`,ua:`Лише картки`},features:[{en:`Counter seating`,ua:`Місця за стійкою`},{en:`Set menu`,ua:`Сет-меню`},{en:`Booking required`,ua:`Потрібне бронювання`}],menu:[`crisp-roast-chicken`,`no-knead-bread`]},{slug:`dnipro-grill`,name:`Dnipro Grill`,meta:{en:`Ukrainian · Dnipro`,ua:`Українська · Дніпро`},text:{en:`Traditional dishes cooked over open fire, from smoked vegetables to slow-braised pork.`,ua:`Традиційні страви на відкритому вогні: від копчених овочів до повільно тушкованої свинини.`},about:{en:`Dnipro Grill cooks traditional Ukrainian dishes over an open fire. Vegetables are smoked, meat is braised slowly, and bread comes warm from the grill.`,ua:`Dnipro Grill готує традиційні українські страви на відкритому вогні. Овочі коптять, м’ясо повільно тушкують, а хліб подають теплим просто з гриля.`},dishes:[{name:{en:`Smoked aubergine salad`,ua:`Салат із копчених баклажанів`},text:{en:`With garlic, herbs and sunflower oil.`,ua:`З часником, зеленню й соняшниковою олією.`}},{name:{en:`Slow-braised pork`,ua:`Повільно тушкована свинина`},text:{en:`Served with buckwheat and pickles.`,ua:`Подається з гречкою та квашеними овочами.`}},{name:{en:`Grilled sourdough`,ua:`Хліб на заквасці з гриля`},text:{en:`Brushed with butter and salt.`,ua:`Змащений маслом і присолений.`}}],address:{en:`30 Riverside Avenue, Dnipro`,ua:`просп. Набережний, 30, Дніпро`},hours:{en:`Daily, 11:00–23:00`,ua:`Щодня, 11:00–23:00`},price:{en:`Mid-range`,ua:`Середній чек`},phone:`+380 56 000 00 03`,wifi:{network:`DniproGrill_Guest`,password:`grill2026`},payment:{en:`Cards and cash`,ua:`Картки та готівка`},features:[{en:`Open-fire kitchen`,ua:`Кухня на відкритому вогні`},{en:`Family tables`,ua:`Столи для компаній`},{en:`Takeaway`,ua:`Страви з собою`}],menu:[`crisp-roast-chicken`,`weeknight-tomato-pasta`,`no-knead-bread`]}];export{e as t};